mapper.select:
SELECT mapping_id, tenant_id, config_id, user_id, im_type, im_user_id, bind_type, bind_time, last_sync_time, status, version
FROM sys_im_user_mapping WHERE tenant_id = #{tenantId} AND im_type = 'WECOM'
ORDER BY mapping_id LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE sys_im_user_mapping SET status = #{afterStatus}, version = version + 1, update_by = #{operator}, update_time = NOW()
WHERE tenant_id = #{tenantId} AND mapping_id = #{mappingId} AND version = #{version}
  AND version < 2147483647 AND im_type = 'WECOM' AND bind_type = 'AUTO_SYNC' AND status = #{beforeStatus}
  AND ((#{afterStatus} = 'DISABLED' AND status IN ('ACTIVE', 'OUT_OF_SCOPE'))
    OR (#{afterStatus} = 'ACTIVE' AND status = 'DISABLED'))

mapper.delete:
DELETE FROM sys_im_user_mapping
WHERE tenant_id = #{tenantId} AND user_id = #{userId} AND mapping_id = #{mappingId}
  AND version = #{version} AND im_type = 'WECOM' AND bind_type IN ('SCAN_BIND', 'MANUAL_BIND')

mapper.select:
SELECT menu_id FROM sys_menu WHERE menu_id IN
#{menuId}
FOR SHARE

SELECT DISTINCT menu.perms FROM sys_menu menu
JOIN sys_role_menu role_menu ON role_menu.menu_id = menu.menu_id AND role_menu.tenant_id = #{tenantId}
JOIN sys_role role_row ON role_row.role_id = role_menu.role_id AND role_row.tenant_id = #{tenantId}
JOIN sys_user_role user_role ON user_role.role_id = role_row.role_id AND user_role.tenant_id = #{tenantId}
WHERE user_role.user_id = #{userId} AND role_row.status = '0' AND role_row.deleted = 0
  AND menu.status = '0' AND menu.perms IS NOT NULL AND menu.perms != ''

SELECT tenant_id, user_id AS id, dept_id AS department_id, user_name AS username, nick_name AS name,
    phonenumber AS mobile, email, avatar, status, deleted, version
FROM sys_user WHERE tenant_id = #{tenantId} ORDER BY user_id LIMIT #{limit}

SELECT tenant_id, mapping_id AS id, config_id, user_id, im_user_id AS external_id, bind_type, last_sync_time, status, version
FROM sys_im_user_mapping WHERE tenant_id = #{tenantId} AND config_id = #{configId} AND im_type = 'WECOM'
ORDER BY mapping_id LIMIT #{limit}

SELECT sync_run_id, tenant_id, config_id, config_version, mode, full_snapshot_flag, status,
    requested_by, started_time, completed_time, create_time, update_time
FROM sys_im_sync_run WHERE tenant_id = #{tenantId} AND config_id = #{configId}
ORDER BY sync_run_id DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE sys_job SET handler_param = #{handlerParam}, cron_expression = #{cronExpression}, status = #{status},
    deleted = 0, version = version + 1, next_fire_time = NULL, update_by = #{updateBy}, update_time = #{updateTime}
WHERE tenant_id = #{tenantId} AND job_id = #{jobId} AND handler_name = 'imOrganizationSync' AND version = #{version}

UPDATE sys_job_log SET result_msg = #{reference}
WHERE tenant_id = #{tenantId} AND job_id = #{jobId} AND execute_no = #{executeNo}
    AND handler_name = 'imOrganizationSync' AND execute_status = 'RUNNING' AND result_msg IS NULL
